package ro.leo.visual;
import ro.leo.i18n.L;
import android.app.*;import android.content.*;import android.database.Cursor;import android.media.*;import android.net.Uri;import android.os.Bundle;import java.util.*;
/** Native keypad tone picker; preview is explicit and stopped on departure. */
public final class SoundSettingsActivity extends LeoActivity {
    private Ringtone preview;private int selected;private final android.os.Handler timer=new android.os.Handler();private final Runnable endPreview=new Runnable(){public void run(){stopPreview();}};
    protected void onResume(){super.onResume();show();}
    protected void onPause(){stopPreview();super.onPause();}
    private void stopPreview(){timer.removeCallbacks(endPreview);if(preview!=null){preview.stop();preview=null;}}
    private String tone(int type){Uri uri=RingtoneManager.getActualDefaultRingtoneUri(this,type);if(uri==null)return type==RingtoneManager.TYPE_ALARM?L.t("Ton de rezervă"):L.t("Silențios");try{Ringtone ringtone=RingtoneManager.getRingtone(this,uri);return ringtone==null?L.t("Indisponibil"):ringtone.getTitle(this);}catch(RuntimeException e){return L.t("Indisponibil");}}
    private void show(){list(L.t("Sunete Leo"),Arrays.asList(L.t("Profil · ")+SoundProfiles.current(this),L.t("Volume separate"),L.t("Apel · ")+tone(RingtoneManager.TYPE_RINGTONE),L.t("Notificări · ")+tone(RingtoneManager.TYPE_NOTIFICATION),L.t("Alarmă · ")+tone(RingtoneManager.TYPE_ALARM),L.t("Nu deranjați"),L.t("Programare Noapte / Silențios")),selected,new Choice(){public void pick(int i){selected=i;if(i==6)startActivity(new Intent(SoundSettingsActivity.this,SoundScheduleActivity.class));else if(i==0)SoundProfiles.select(SoundSettingsActivity.this,new Runnable(){public void run(){show();}});else if(i==1)startActivity(new Intent(SoundSettingsActivity.this,QuickSettingsActivity.class).putExtra("volumes",true));else if(i<5)tones(new int[]{RingtoneManager.TYPE_RINGTONE,RingtoneManager.TYPE_NOTIFICATION,RingtoneManager.TYPE_ALARM}[i-2]);else dnd();}},"",null);}
    private void tones(final int type){stopPreview();begin(L.t("Tonuri · se încarcă"));root.addView(text(L.t("Se citește biblioteca Android…"),17));footer("","",L.t("Înapoi"));worker.execute(new Runnable(){public void run(){final ArrayList<String> names=new ArrayList<String>();final ArrayList<Uri> sources=new ArrayList<Uri>();if(type!=RingtoneManager.TYPE_ALARM){names.add(L.t("Silențios"));sources.add(null);}RingtoneManager manager=new RingtoneManager(SoundSettingsActivity.this);try{manager.setType(type);Cursor cursor=manager.getCursor();if(cursor!=null)try{while(cursor.moveToNext()&&names.size()<201){sources.add(manager.getRingtoneUri(cursor.getPosition()));names.add(cursor.getString(RingtoneManager.TITLE_COLUMN_INDEX));}}finally{cursor.close();}}catch(RuntimeException denied){}ui(new Runnable(){public void run(){list(L.t("Alege tonul"),names,0,new Choice(){public void pick(final int at){options(names.get(at),new String[]{L.t("Aplică tonul"),L.t("Ascultă proba"),L.t("Oprește proba")},new Choice(){public void pick(int command){if(command==0){stopPreview();try{RingtoneManager.setActualDefaultRingtoneUri(SoundSettingsActivity.this,type,sources.get(at));notice(L.t("Ton salvat"));show();}catch(RuntimeException denied){notice(L.t("Tonul nu poate fi schimbat"));}}else if(command==2)stopPreview();else{stopPreview();if(sources.get(at)==null){notice(L.t("Ton silențios"));return;}try{preview=RingtoneManager.getRingtone(SoundSettingsActivity.this,sources.get(at));if(preview!=null){preview.play();timer.postDelayed(endPreview,8000);}}catch(RuntimeException failed){notice(L.t("Proba nu poate fi redată"));}}}});}},L.t("Înapoi"),new Runnable(){public void run(){stopPreview();show();}});back=new Runnable(){public void run(){stopPreview();show();}};}});}});}
    private void dnd(){final NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(!nm.isNotificationPolicyAccessGranted()){notice(L.t("Acces Nu deranjați neacordat"));return;}options(L.t("Nu deranjați"),new String[]{L.t("Oprit"),L.t("Doar prioritare"),L.t("Doar alarme"),L.t("Fără întreruperi, inclusiv alarme")},new Choice(){public void pick(int i){try{nm.setInterruptionFilter(new int[]{NotificationManager.INTERRUPTION_FILTER_ALL,NotificationManager.INTERRUPTION_FILTER_PRIORITY,NotificationManager.INTERRUPTION_FILTER_ALARMS,NotificationManager.INTERRUPTION_FILTER_NONE}[i]);show();}catch(RuntimeException e){notice(L.t("Setarea nu poate fi schimbată"));}}});}
}
